def choose_move(observation):
    x = 0
    y = 0
    if isinstance(observation, dict):
        pos = observation.get('self_position', {})
        x = pos.get('x', 0)
        y = pos.get('y', 0)
        grid_w = observation.get('grid_width', 0)
        grid_h = observation.get('grid_height', 0)
    else:
        grid_w = 0
        grid_h = 0

    def clamp(d):
        if d < -1:
            return -1
        if d > 1:
            return 1
        return d

    resources = observation.get('resources', []) if isinstance(observation, dict) else []
    if isinstance(resources, list) and resources:
        best = None
        best_dist = 10**9
        for r in resources:
            rx = r.get('x', 0)
            ry = r.get('y', 0)
            dist = abs(rx - x) + abs(ry - y)
            if dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            return [clamp(rx - x), clamp(ry - y)]

    opponents = observation.get('opponent_position', {}) if isinstance(observation, dict) else {}
    ox = opponents.get('x', 0) if isinstance(opponents, dict) else 0
    oy = opponents.get('y', 0) if isinstance(opponents, dict) else 0
    if isinstance(opponents, dict) and (ox != 0 or oy != 0):
        return [clamp(ox - x), clamp(oy - y)]

    # Fallback: stay or step towards center if possible
    if grid_w and grid_h:
        cx = min(max(grid_w // 2, 0), grid_w - 1)
        cy = min(max(grid_h // 2, 0), grid_h - 1)
        return [clamp(cx - x), clamp(cy - y)]

    return [0, 0]
